local _, WFJ = ...
WFJ.Data.add("book", {
  ["d203a8dbd833e8e9"] = { "KORMOK\n\nNegromante ogre a due teste\n\nChe dire di Kormok? Era un ogre a due teste, di quelli che lanciano incantesimi, e un tempo non era poi così cattivo. Quando lo accogliemmo tra noi era un prigioniero, catturato durante un incarico che avevamo accettato nelle ⟦Burning Steppes=Steppe Ardenti⟧. Lì però si rivelò prezioso per aiutarci a uscire da una brutta situazione in cui eravamo finiti, e così entrò nella compagnia come uno dei suoi maghi migliori.\n\nLa cosa strana di lui, però, era la natura completamente diversa delle sue due teste. Una era sempre allegra, se non un po' sciocca, mentre l'altra era scaltra, calcolatrice e aveva uno sguardo quasi morto. A dire il vero, metteva i brividi.", "." },
  ["d2122f7c35fdc414"] = { "<HTML>\n<BODY>\n<H1 align=\"center\">GRADI DEGLI UFFICIALI DELL'ALLEANZA</H1><BR/>\n<P align=\"center\">Parte 2</P>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank09\" align=\"left\"/><BR/>\n<P align=\"right\">Cavalier Campione</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank08\" align=\"left\"/><BR/>\n<P align=\"right\">Cavalier Capitano</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank07\" align=\"left\"/><BR/>\n<P align=\"right\">Cavalier Tenente</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank06\" align=\"left\"/><BR/>\n<P align=\"right\">Cavaliere</P><BR/><BR/>\n</BODY>\n</HTML>", "." },
  ["d26f97043a27e58c"] = { "Corroborante.\n\nFarne di più. Più corroborante.\n\nCorroborante rende forti Freddinverno. Sconfiggere nostri nemici.\n\nFreddinverno non hanno alleati. Freddinverno sono forti. Hanno grande potere.", "." },
  ["d29bfc2183dc8dd1"] = { "La sorte di Joseph Redpath\n\nJoseph Redpath fu ucciso durante la battaglia del ⟦Darrowshire=Borgo di Darrow⟧. Il suo spirito fu corrotto e assunse una nuova forma, e questa creatura diffuse un grande male in Lordaeron.\n\nAl ⟦Gahrron's Withering=Podere di Gahrron⟧, a est di Andorhal, il Redpath corrotto fu infine sconfitto dalle forze dell'⟦Alliance=Alleanza⟧. Il suo scudo giace ancora vicino al fienile della fattoria appestata, e i servitori del Flagello sono ancora attratti dal ricordo della sua malvagità.", "." },
  ["d2a137f704e47e65"] = { "Quando guardi nell'Occhio, la tua mente si riempie delle immagini di una grande battaglia..\n\nQuesto terribile scontro sembra svolgersi da qualche parte a Lordaeron..\n\nRiesci a malapena a distinguere una figura femminile solitaria, in piedi tra mille cadaveri, che respinge una marea del Flagello..\n\nÈ in disperata inferiorità numerica..\n\nFilamenti di luce le sfuggono dalle mani e falciano i non morti a centinaia.", "." },
  ["d2d18369fdb1feb1"] = { "Reuben,\n\nti scrivo questa lettera sapendo che forse non la vedrai mai; semplicemente non riesco a restare con le mani in mano, ad ascoltare i colpi incessanti contro le mura di ⟦Hearthglen=Valsalda⟧. I non morti sono fuori dal nostro villaggio, instancabili nel loro assalto, e abbiamo il compito di difendere gli abitanti finché non arriveranno i rinforzi.\n\nNell'ultima carica mi sono rotto una gamba, e così sto seduto qui, inutile, con la spada al fianco nel caso le nostre difese venissero sfondate. Nessuno scherza più... si sentono solo i rumori della battaglia e della morte. L'aria è densa di paura.\n\nIl principe Arthas è qui e combatte in prima linea con gli uomini. Se non ci fosse lui, saremmo caduti da tempo. Il suo amore per questa terra e per la sua gente è contagioso; servo sotto di lui con gioia, e lo farò fino alla fine dei miei giorni.\n\nI combattimenti si fanno più intensi; gamba rotta o no, non posso restare seduto qui. Serve ogni spada. Spero che queste parole ti trovino in tempi più felici.\n\nIl tuo amico,\n\nLeagrem", "." },
})
